head.script:
scwin.onpageload = function() {
    scwin.itemCodeMap = {
        "01": "기획/전략 수립",
        "02": "화면 설계 및 기획",
        "03": "UI/UX 컴포넌트 개발",
        "04": "백엔드 API 연동",
        "05": "품질 테스트 및 QA",
        "06": "서버 배포 및 모니터링",
        "07": "사용자 매뉴얼 작성"
    };
};

scwin.fn_formatMultiCheck = function(data) {
    if (!data || typeof data !== "string" || data.trim() === "") {
        if (window.parent && window.parent.scwin && window.parent.scwin._isExcelDownloading) {
            return "";
        }
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }

    var codeList = data.split(",");
    var labelList = [];
    for (var i = 0; i < codeList.length; i++) {
        var code = codeList[i].trim();
        if (code !== "") {
            var label = (scwin.itemCodeMap && scwin.itemCodeMap[code]) ? scwin.itemCodeMap[code] : code;
            labelList.push(label);
        }
    }

    if (labelList.length === 0) {
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }
    return labelList.join("<br/>");
};

scwin.fn_getGridCellDom = function(gridObj, row, col) {
    var gridId = (typeof gridObj.getID === "function") ? gridObj.getID() : gridObj.id;
    var cellDom = document.getElementById(gridId + "_cell_" + row + "_" + col);
    if (cellDom) return cellDom;

    var evt = window.event;
    if (evt && evt.target) {
        var td = evt.target.closest ? evt.target.closest("td") : null;
        if (td) return td;
    }
    if (typeof gridObj.getCellElement === "function") {
        return gridObj.getCellElement(row, col);
    }
    return null;
};

scwin.grd_team_oncellclick = function(row, col) {
    var colId = grd_team.getColumnID(col);
    if (colId !== "taskCodes") return;

    var cellDom = scwin.fn_getGridCellDom(grd_team, row, col);
    if (!cellDom) return;

    var rawValue = dlt_team.getCellData(row, colId) || "";
    var selectedCodes = rawValue ? rawValue.split(",").map(function(c) { return c.trim(); }) : [];
    scwin.fn_openMultiCheckLayer(cellDom, row, colId, selectedCodes, dlt_team);
};

scwin.fn_openMultiCheckLayer = function(cellDom, row, colId, selectedCodes, dataListObj) {
    var layer = document.getElementById("ws_floating_multicheck_team");
    if (!layer) return;

    layer.targetRow = row;
    layer.targetColId = colId;
    layer.targetDataList = dataListObj;
    layer.checkedCodeMap = {};

    for (var i = 0; i < selectedCodes.length; i++) {
        var c = selectedCodes[i];
        if (c) layer.checkedCodeMap[c] = true;
    }

    var rect = cellDom.getBoundingClientRect();
    var layerWidth = 260;
    var layerHeight = 270;
    var top = rect.bottom + 2;
    var left = rect.left;

    if (top + layerHeight > window.innerHeight && rect.top - layerHeight > 0) {
        top = rect.top - layerHeight - 2;
    }
    if (left + layerWidth > window.innerWidth) {
        left = window.innerWidth - layerWidth - 10;
    }

    layer.style.top = top + "px";
    layer.style.left = left + "px";
    layer.style.display = "block";

    var searchInput = document.getElementById("ws_multicheck_input_team");
    if (searchInput) {
        searchInput.value = "";
        searchInput.focus();
    }
    scwin.fn_renderCheckList("");
};

scwin.fn_renderCheckList = function(keyword) {
    var listContainer = document.getElementById("ws_multicheck_list_team");
    var layer = document.getElementById("ws_floating_multicheck_team");
    if (!listContainer || !layer) return;

    listContainer.innerHTML = "";
    var kw = (keyword || "").toLowerCase().trim();
    var checkedMap = layer.checkedCodeMap || {};

    var items = [];
    for (var code in scwin.itemCodeMap) {
        var label = scwin.itemCodeMap[code];
        if (!kw || label.toLowerCase().includes(kw) || code.includes(kw)) {
            items.push({ code: code, label: label, isChecked: !!checkedMap[code] });
        }
    }

    items.sort(function(a, b) {
        if (a.isChecked && !b.isChecked) return -1;
        if (!a.isChecked && b.isChecked) return 1;
        return a.code.localeCompare(b.code);
    });

    items.forEach(function(item) {
        var labelEl = document.createElement("label");
        labelEl.className = "ws-multicheck-item" + (item.isChecked ? " is-checked" : "");
        labelEl.innerHTML = 
            '<input type="checkbox" value="' + item.code + '" ' + (item.isChecked ? 'checked' : '') + ' />' +
            '<span>[' + item.code + '] ' + item.label + '</span>';

        var chk = labelEl.querySelector("input");
        chk.addEventListener("change", function() {
            var val = this.value;
            if (this.checked) {
                checkedMap[val] = true;
                labelEl.classList.add("is-checked");
            } else {
                delete checkedMap[val];
                labelEl.classList.remove("is-checked");
            }
        });
        listContainer.appendChild(labelEl);
    });

    if (items.length === 0) {
        listContainer.innerHTML = '<div style="padding:15px; text-align:center; color:#94a3b8;">일치하는 항목이 없습니다.</div>';
    }
};

scwin.btn_apply_onclick = function() {
    var layer = document.getElementById("ws_floating_multicheck_team");
    if (!layer) return;

    var finalCodes = Object.keys(layer.checkedCodeMap || {});
    var resultValue = finalCodes.join(",");
    layer.targetDataList.setCellData(layer.targetRow, layer.targetColId, resultValue);
    scwin.fn_closeMultiCheckLayer();
};

scwin.fn_closeMultiCheckLayer = function() {
    var layer = document.getElementById("ws_floating_multicheck_team");
    if (layer) layer.style.display = "none";
};
